import React, { useState, useEffect, useRef, useCallback } from 'react';

export interface LoginScreenProps {
  identifier: string;
  prefill_identifier?: string;
  onOtpSent?: (payload: { channel: 'email' | 'sms' }) => void;
  onOtpResent?: () => void;
  onLoginSucceeded?: (payload: { user_id: string }) => void;
  onLoginFailed?: (payload: { reason: 'invalid_otp' | 'expired' | 'locked' | 'network' }) => void;
}

const MAX_ATTEMPTS = 5;
const LOCKOUT_MS = 15 * 60 * 1000;
const OTP_TTL_MS = 10 * 60 * 1000;
const RESEND_COOLDOWN_S = 30;

const isEmail = (v: string) => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v);
const isPhone = (v: string) => /^\+[1-9]\d{6,14}$/.test(v);

const LoginScreen: React.FC<LoginScreenProps> = ({
  identifier,
  prefill_identifier,
  onOtpSent,
  onOtpResent,
  onLoginSucceeded,
  onLoginFailed,
}) => {
  const [value, setValue] = useState<string>(prefill_identifier ?? identifier ?? '');
  const [stage, setStage] = useState<'identifier' | 'otp'>('identifier');
  const [otp, setOtp] = useState<string>('');
  const [error, setError] = useState<string>('');
  const [info, setInfo] = useState<string>('');
  const [attempts, setAttempts] = useState<number>(0);
  const [lockedUntil, setLockedUntil] = useState<number | null>(null);
  const [otpSentAt, setOtpSentAt] = useState<number | null>(null);
  const [resendCooldown, setResendCooldown] = useState<number>(0);
  const [channel, setChannel] = useState<'email' | 'sms' | null>(null);
  const otpInputRef = useRef<HTMLInputElement | null>(null);

  useEffect(() => {
    if (resendCooldown <= 0) return;
    const t = setTimeout(() => setResendCooldown((c) => c - 1), 1000);
    return () => clearTimeout(t);
  }, [resendCooldown]);

  useEffect(() => {
    if (!lockedUntil) return;
    const t = setInterval(() => {
      if (Date.now() >= lockedUntil) {
        setLockedUntil(null);
        setAttempts(0);
        setError('');
      }
    }, 1000);
    return () => clearInterval(t);
  }, [lockedUntil]);

  const isLocked = lockedUntil !== null && Date.now() < lockedUntil;

  const sendOtp = useCallback(
    (resend: boolean) => {
      setError('');
      const v = value.trim();
      const ch: 'email' | 'sms' | null = isEmail(v) ? 'email' : isPhone(v) ? 'sms' : null;
      if (!ch) {
        setError('Bitte gültige E-Mail oder Telefonnummer (E.164) eingeben.');
        return;
      }
      setChannel(ch);
      setOtpSentAt(Date.now());
      setResendCooldown(RESEND_COOLDOWN_S);
      setTimeout(() => {
        setStage('otp');
        setInfo(resend ? 'OTP erneut gesendet.' : `OTP an ${ch === 'email' ? 'E-Mail' : 'Telefon'} gesendet.`);
        if (resend) onOtpResent?.();
        else onOtpSent?.({ channel: ch });
        setTimeout(() => otpInputRef.current?.focus(), 50);
      }, 100);
    },
    [value, onOtpSent, onOtpResent],
  );

  const handleSubmitIdentifier = (e: React.FormEvent) => {
    e.preventDefault();
    if (isLocked) return;
    sendOtp(false);
  };

  const handleVerify = (e: React.FormEvent) => {
    e.preventDefault();
    if (isLocked) return;
    setError('');
    setInfo('');

    if (otpSentAt && Date.now() - otpSentAt > OTP_TTL_MS) {
      setError('Der Code ist abgelaufen. Bitte erneut anfordern.');
      onLoginFailed?.({ reason: 'expired' });
      return;
    }

    if (!/^\d{6}$/.test(otp)) {
      setError('Bitte 6-stelligen Code eingeben.');
      onLoginFailed?.({ reason: 'invalid_otp' });
      return;
    }

    if (otp === '123456') {
      setAttempts(0);
      onLoginSucceeded?.({ user_id: `user_${value.trim()}` });
      setInfo('Login erfolgreich.');
      return;
    }

    const next = attempts + 1;
    setAttempts(next);
    if (next >= MAX_ATTEMPTS) {
      const until = Date.now() + LOCKOUT_MS;
      setLockedUntil(until);
      setError('Zu viele Fehlversuche. Konto für 15 Minuten gesperrt.');
      onLoginFailed?.({ reason: 'locked' });
    } else {
      setError(`Ungültiger Code. Versuche übrig: ${MAX_ATTEMPTS - next}.`);
      onLoginFailed?.({ reason: 'invalid_otp' });
    }
  };

  const handleResend = () => {
    if (isLocked || resendCooldown > 0) return;
    sendOtp(true);
  };

  const lockoutRemaining = lockedUntil ? Math.max(0, Math.ceil((lockedUntil - Date.now()) / 1000)) : 0;

  return (
    <div
      role="main"
      aria-labelledby="login-title"
      style={{
        maxWidth: 420,
        margin: '2rem auto',
        padding: '1.5rem',
        border: '1px solid #ccc',
        borderRadius: 8,
        fontFamily: 'system-ui, sans-serif',
        color: '#111',
        background: '#fff',
      }}
    >
      <h1 id="login-title" style={{ fontSize: '1.4rem', marginTop: 0 }}>
        Anmelden
      </h1>

      {isLocked && (
        <div role="alert" style={{ background: '#fde2e2', padding: '0.75rem', borderRadius: 4, marginBottom: '1rem' }}>
          Gesperrt. Bitte in {lockoutRemaining}s erneut versuchen.
        </div>
      )}

      {stage === 'identifier' && (
        <form onSubmit={handleSubmitIdentifier} noValidate>
          <label htmlFor="identifier-input" style={{ display: 'block', marginBottom: 4 }}>
            E-Mail oder Telefonnummer
          </label>
          <input
            id="identifier-input"
            type="text"
            value={value}
            onChange={(e) => setValue(e.target.value)}
            autoComplete="username"
            aria-required="true"
            aria-invalid={!!error}
            disabled={isLocked}
            style={{ width: '100%', padding: '0.5rem', fontSize: '1rem', boxSizing: 'border-box' }}
          />
          <button
            type="submit"
            disabled={isLocked || !value.trim()}
            style={{
              marginTop: '1rem',
              width: '100%',
              padding: '0.6rem',
              fontSize: '1rem',
              background: '#1d4ed8',
              color: '#fff',
              border: 'none',
              borderRadius: 4,
              cursor: 'pointer',
            }}
          >
            Code senden
          </button>
        </form>
      )}

      {stage === 'otp' && (
        <form onSubmit={handleVerify} noValidate>
          <p style={{ marginTop: 0 }}>
            Code gesendet an <strong>{value}</strong>
            {channel ? ` (${channel === 'email' ? 'E-Mail' : 'SMS'})` : ''}.
          </p>
          <label htmlFor="otp-input" style={{ display: 'block', marginBottom: 4 }}>
            6-stelliger Code
          </label>
          <input
            id="otp-input"
            ref={otpInputRef}
            type="text"
            inputMode="numeric"
            pattern="\d{6}"
            maxLength={6}
            value={otp}
            onChange={(e) => setOtp(e.target.value.replace(/\D/g, ''))}
            autoComplete="one-time-code"
            aria-required="true"
            aria-invalid={!!error}
            disabled={isLocked}
            style={{ width: '100%', padding: '0.5rem', fontSize: '1.25rem', letterSpacing: '0.3em', boxSizing: 'border-box' }}
          />
          <button
            type="submit"
            disabled={isLocked || otp.length !== 6}
            style={{
              marginTop: '1rem',
              width: '100%',
              padding: '0.6rem',
              fontSize: '1rem',
              background: '#1d4ed8',
              color: '#fff',
              border: 'none',
              borderRadius: 4,
              cursor: 'pointer',
            }}
          >
            Bestätigen
          </button>
          <div style={{ marginTop: '0.75rem', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
            <button
              type="button"
              onClick={handleResend}
              disabled={isLocked || resendCooldown > 0}
              style={{
                background: 'none',
                border: 'none',
                color: '#1d4ed8',
                cursor: resendCooldown > 0 ? 'not-allowed' : 'pointer',
                padding: 0,
                textDecoration: 'underline',
              }}
            >
              {resendCooldown > 0 ? `Erneut senden (${resendCooldown}s)` : 'Code erneut senden'}
            </button>
            <button
              type="button"
              onClick={() => {
                setStage('identifier');
                setOtp('');
                setError('');
                setInfo('');
              }}
              style={{ background: 'none', border: 'none', color: '#555', cursor: 'pointer' }}
            >
              Zurück
            </button>
          </div>
        </form>
      )}

      <div aria-live="polite" style={{ marginTop: '1rem', minHeight: '1.25rem' }}>
        {error && (
          <p role="alert" style={{ color: '#b91c1c', margin: 0 }}>
            {error}
          </p>
        )}
        {!error && info && <p style={{ color: '#065f46', margin: 0 }}>{info}</p>}
      </div>
    </div>
  );
};

export default LoginScreen;
